#!/usr/bin/env node
/**
 * add-manager-to-scene.js
 *
 * Adds a manager node (Node + Component) to a Cocos Creator scene file.
 * The component type UUID is read from the .meta file generated by Cocos Creator.
 *
 * Usage:
 *   node tools/add-manager-to-scene.js \
 *     --scene assets/scenes/StartDefault.scene \
 *     --meta assets/scripts/Managers/Global/LocalizationManager.ts.meta \
 *     --name LocalizationManager \
 *     [--position first|last]  (default: first)
 *     [--dry-run]
 *
 * The script is idempotent: if a node with the given name already exists, it skips.
 *
 * Prerequisites:
 *   - The TypeScript file must exist and Cocos Creator must have generated its .meta file.
 */

const fs = require('fs');
const path = require('path');
const crypto = require('crypto');

const ROOT_DIR = process.env.CLAUDE_PROJECT_DIR || process.cwd();

function parseArgs() {
    const args = process.argv.slice(2);
    const result = { scene: null, meta: null, name: null, position: 'first', dryRun: false, properties: {} };

    for (let i = 0; i < args.length; i++) {
        if (args[i] === '--scene') result.scene = args[++i];
        else if (args[i] === '--meta') result.meta = args[++i];
        else if (args[i] === '--name') result.name = args[++i];
        else if (args[i] === '--position') result.position = args[++i];
        else if (args[i] === '--dry-run') result.dryRun = true;
        else if (args[i] === '--properties') {
            try {
                result.properties = JSON.parse(args[++i]);
            } catch (e) {
                console.error('Invalid --properties JSON:', e.message);
                process.exit(1);
            }
        }
    }

    if (!result.scene || !result.meta || !result.name) {
        console.error('Usage: node add-manager-to-scene.js --scene <path> --meta <path> --name <NodeName> [--position first|last] [--properties <JSON>] [--dry-run]');
        process.exit(1);
    }

    return result;
}

/**
 * Converts a full hyphenated UUID (from .meta file) to Cocos Creator's compact 23-char format.
 * Algorithm: first 5 hex chars pass-through, remaining 27 hex + '0' → base64 → first 18 chars.
 */
function compressUuid(uuid) {
    const hex = uuid.replace(/-/g, '');
    const tail = Buffer.from(hex.slice(5) + '0', 'hex').toString('base64').slice(0, 18);
    return hex.slice(0, 5) + tail;
}

function readMeta(metaPath) {
    const abs = path.resolve(ROOT_DIR, metaPath);
    if (!fs.existsSync(abs)) {
        console.error(`Meta file not found: ${abs}`);
        console.error('Make sure the TypeScript file exists and Cocos Creator has generated its .meta file.');
        process.exit(1);
    }
    const meta = JSON.parse(fs.readFileSync(abs, 'utf8'));
    const uuid = meta.uuid;
    if (!uuid) {
        console.error('No uuid found in meta file');
        process.exit(1);
    }
    return compressUuid(uuid);
}

function generateId() {
    return crypto.randomBytes(16).toString('base64').replace(/[+/=]/g, c =>
        c === '+' ? '-' : c === '/' ? '_' : ''
    ).slice(0, 22);
}

function findSceneNode(objects) {
    for (let i = 0; i < objects.length; i++) {
        if (objects[i].__type__ === 'cc.Scene') return i;
    }
    return -1;
}

function nodeExists(objects, name) {
    return objects.some(obj => obj.__type__ === 'cc.Node' && obj._name === name);
}

const args = parseArgs();
const componentType = readMeta(args.meta);
console.log(`Component UUID: ${componentType}`);

const sceneAbs = path.resolve(ROOT_DIR, args.scene);
if (!fs.existsSync(sceneAbs)) {
    console.error(`Scene file not found: ${sceneAbs}`);
    process.exit(1);
}

let objects;
try {
    objects = JSON.parse(fs.readFileSync(sceneAbs, 'utf8'));
} catch (e) {
    console.error(`Failed to parse scene: ${e.message}`);
    process.exit(1);
}

if (!Array.isArray(objects)) {
    console.error('Scene file is not a JSON array');
    process.exit(1);
}

if (nodeExists(objects, args.name)) {
    console.log(`Node "${args.name}" already exists in ${args.scene} — skipping`);
    process.exit(0);
}

const sceneIdx = findSceneNode(objects);
if (sceneIdx < 0) {
    console.error('Could not find cc.Scene object in scene file');
    process.exit(1);
}

const nodeIdx = objects.length;
const compIdx = objects.length + 1;

const newNode = {
    __type__: 'cc.Node',
    _name: args.name,
    _objFlags: 0,
    __editorExtras__: {},
    _parent: { __id__: sceneIdx },
    _children: [],
    _active: true,
    _components: [{ __id__: compIdx }],
    _prefab: null,
    _lpos: { __type__: 'cc.Vec3', x: 0, y: 0, z: 0 },
    _lrot: { __type__: 'cc.Quat', x: 0, y: 0, z: 0, w: 1 },
    _lscale: { __type__: 'cc.Vec3', x: 1, y: 1, z: 1 },
    _mobility: 0,
    _layer: 1073741824,
    _euler: { __type__: 'cc.Vec3', x: 0, y: 0, z: 0 },
    _id: generateId(),
};

const newComp = {
    __type__: componentType,
    _name: '',
    _objFlags: 0,
    __editorExtras__: {},
    node: { __id__: nodeIdx },
    _enabled: true,
    __prefab: null,
    ...args.properties,
    _id: generateId(),
};

objects.push(newNode, newComp);

const scene = objects[sceneIdx];
if (!Array.isArray(scene._children)) {
    scene._children = [];
}

if (args.position === 'first') {
    scene._children.unshift({ __id__: nodeIdx });
} else {
    scene._children.push({ __id__: nodeIdx });
}

console.log(`Added node "${args.name}" (node idx=${nodeIdx}, comp idx=${compIdx}) to cc.Scene at position: ${args.position}`);

if (!args.dryRun) {
    fs.writeFileSync(sceneAbs, JSON.stringify(objects, null, 2), 'utf8');
    console.log(`Saved: ${sceneAbs}`);
} else {
    console.log('[DRY RUN] No file written');
}
